const text = "Maria Chen joined Northwind Freight, a company in Chicago.";
const found = await tt.recognize(text, {
  kinds: ["person", "organization", "place"],
  relations: { works_for: ["person", "organization"],
               based_in: ["organization", "place"] },
});
// 1 Maria Chen, a person; 2 Northwind Freight, an
// organization; 3 Chicago, a place
for (const name of found.entities) console.log(name.id, name.text, name.kind);
// works_for 1 → 2, and based_in 2 → 3
for (const link of found.relations) console.log(link.name, link.source, link.target);
